package br.com.admeclesial.interfaces.rest.pessoa;

import br.com.admeclesial.application.pessoa.*; import br.com.admeclesial.domain.pessoa.MembroFamilia; import jakarta.validation.Valid; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/v1/membros-familia") public class MembroFamiliaRestController { final MembroFamiliaApplicationService s; public MembroFamiliaRestController(MembroFamiliaApplicationService s){this.s=s;} @PostMapping public MembroFamilia criar(@Valid @RequestBody MembroFamiliaRequest r){return s.criar(r);} @GetMapping public List<MembroFamilia> listar(){return s.listar();} @GetMapping("/{uuid}") public MembroFamilia buscar(@PathVariable UUID uuid){return s.buscar(uuid);} @GetMapping("/por-familia") public List<MembroFamilia> porFamilia(@RequestParam UUID familiaUuid){return s.listarPorFamilia(familiaUuid);} @PostMapping("/{uuid}/encerrar") public MembroFamilia encerrar(@PathVariable UUID uuid,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate dataFim){return s.encerrar(uuid,dataFim);} }
